// REAL MNIST test digits for the anatomy diagrams — the first test-set
// occurrence of each class 0..9, read from torchvision's raw idx files
// (/private/tmp/mini_networks_test_data/MNIST/raw/t10k-images-idx3-ubyte,
// t10k-labels-idx1-ubyte). Each digit is 28×28 uint8 (0..255), row-major,
// as a 1568-char hex string. Generated by a one-off numpy extraction
// (no binary files in git — data lives as TS text).
export interface MnistDigit { index: number; label: number; hex: string }

export const MNIST_DIGITS: readonly MnistDigit[] = [
  { index: 3, label: 0, hex: "" },
  { index: 2, label: 1, hex: "" },
  { index: 1, label: 2, hex: "" },
  { index: 18, label: 3, hex: "" },
  { index: 4, label: 4, hex: "" },
  { index: 8, label: 5, hex: "" },
  { index: 11, label: 6, hex: "" },
  { index: 0, label: 7, hex: "" },
  { index: 61, label: 8, hex: "" },
  { index: 7, label: 9, hex: "" },
];

/** 28×28 digit → Float32Array in [-1, 1] (the trainers' x*2-1 convention). */
export function digitPixels(d: MnistDigit): Float32Array {
  const out = new Float32Array(784);
  for (let i = 0; i < 784; i++) out[i] = (parseInt(d.hex.slice(2 * i, 2 * i + 2), 16) / 255) * 2 - 1;
  return out;
}

export const digitByLabel = (label: number): MnistDigit => MNIST_DIGITS[((label % 10) + 10) % 10];
